export type TaskStatus =
  | "working"         // The request is currently being processed
  | "input_required"  // The task is waiting for input (e.g., elicitation or sampling)
  | "completed"       // The request completed successfully and results are available
  | "failed"          // The associated request failed due to a JSON-RPC error during execution
  | "cancelled";      // The request was cancelled before completion

export interface Task {
  taskId: string;
  status: TaskStatus;
  /** Optional human-readable message describing the current task state. */
  statusMessage?: string;
  /** ISO 8601 timestamp when the task was created. */
  createdAt: string;
  /** ISO 8601 timestamp when the task was last updated. */
  lastUpdatedAt: string;
  /**
   * Time-to-live duration from creation in integer milliseconds, null for unlimited.
   * The server may discard the task after the TTL elapses. This value MAY change
   * over the lifetime of a task.
   * @nullable
   */
  ttlMs: number | null;
  /**
   * Suggested polling interval in integer milliseconds. Clients SHOULD honor
   * this value to avoid overwhelming the server. This value MAY change over
   * the lifetime of a task.
   */
  pollIntervalMs?: number;
}

export interface WorkingTask extends Task { status: "working"; }
export interface InputRequiredTask extends Task {
  status: "input_required";
  inputRequests: InputRequests;
}
export interface CompletedTask extends Task {
  status: "completed";
  /** Structure matches the result type of the original request. */
  result: { [key: string]: unknown };
}
export interface FailedTask extends Task {
  status: "failed";
  error: { [key: string]: unknown };
}
export interface CancelledTask extends Task { status: "cancelled"; }

export type DetailedTask =
  | WorkingTask | InputRequiredTask | CompletedTask | FailedTask | CancelledTask;

/** resultType MUST be "task". This type is Result & Task (flat). */
export type CreateTaskResult = Result & Task;

export interface GetTaskRequest extends JSONRPCRequest {
  method: "tasks/get";
  params: { taskId: string };
}
/** resultType MUST be "complete". */
export type GetTaskResult = Result & DetailedTask;

export interface UpdateTaskRequest extends JSONRPCRequest {
  method: "tasks/update";
  params: {
    taskId: string;
    /** Each key MUST correspond to a currently-outstanding inputRequest key. */
    inputResponses: InputResponses;
  };
}
export type UpdateTaskResult = Result;  // empty ack

export interface CancelTaskRequest extends JSONRPCRequest {
  method: "tasks/cancel";
  params: { taskId: string };
}
export type CancelTaskResult = Result;  // empty ack; cooperative, eventually consistent

export type TaskStatusNotificationParams =
  NotificationParams & DetailedTask & { [key: string]: unknown };

export interface TaskStatusNotification extends JSONRPCNotification {
  method: "notifications/tasks";
  params: TaskStatusNotificationParams;
}

/** subscriptions/listen additions */
export interface TaskSubscriptionNotifications { taskIds?: string[]; }
export interface TaskSubscriptionAcknowledgedNotifications { taskIds?: string[]; }

/** Empty object indicates support; no settings defined. */
export type TasksExtensionCapability = Record<string, never>;

export type ResultType = "complete" | "input_required" | string;

export interface Result {
  _meta?: ResultMetaObject;
  /**
   * Servers implementing this protocol version MUST include this field.
   * For backward compatibility, when a client receives a result from a
   * server implementing an earlier protocol version (which does not include
   * `resultType`), the client MUST treat the absent field as `"complete"`.
   */
  resultType: ResultType;
  [key: string]: unknown;
}

export interface PaginatedResult extends Result {
  /** Opaque token for the position after the last returned result. */
  nextCursor?: Cursor;
}

export interface CacheableResult extends Result {
  /**
   * How long (ms) the client MAY cache this response. Analogous to
   * HTTP Cache-Control max-age. 0 => immediately stale.
   * @minimum 0
   */
  ttlMs: number;
  /**
   * "public": no user-specific data; any client or intermediary MAY cache
   *   and serve it across authorization contexts.
   * "private": cacheable and reusable only within the same authorization
   *   context. Caches MUST NOT be shared across authorization contexts.
   */
  cacheScope: "public" | "private";
}

export interface RequestMetaObject extends MetaObject {
  /** Opaque token for out-of-band notifications/progress. */
  progressToken?: ProgressToken;

  /**
   * The MCP Protocol Version being used for this request. Required.
   * For the HTTP transport, this value MUST match the `MCP-Protocol-Version`
   * header; otherwise the server MUST return a `400 Bad Request`. If the
   * server does not support the requested version, it MUST return an
   * UnsupportedProtocolVersionError.
   */
  "io.modelcontextprotocol/protocolVersion": string;

  /**
   * Identifies the client software making the request. Clients SHOULD
   * include this field on every request. Self-reported, not verified.
   * Servers SHOULD NOT rely on it for security decisions.
   */
  "io.modelcontextprotocol/clientInfo"?: Implementation;

  /**
   * The client's capabilities for this specific request. Required.
   * Capabilities are declared per-request rather than once at initialization;
   * an empty object means the client supports no optional capabilities.
   * Servers MUST NOT infer capabilities from prior requests.
   */
  "io.modelcontextprotocol/clientCapabilities": ClientCapabilities;

  /** @deprecated as of 2026-07-28 (SEP-2577). Replaces logging/setLevel. */
  "io.modelcontextprotocol/logLevel"?: LoggingLevel;
}

export interface ResultMetaObject extends MetaObject {
  "io.modelcontextprotocol/serverInfo"?: Implementation;
}

export interface NotificationMetaObject extends MetaObject {
  /** JSON-RPC ID of the subscriptions/listen request that opened the stream. */
  "io.modelcontextprotocol/subscriptionId"?: RequestId;
}

export interface Tool extends BaseMetadata, Icons {
  description?: string;
  /**
   * Tool arguments are always JSON objects, so `type: "object"` is required at the
   * root. Beyond that, any JSON Schema 2020-12 keyword may appear alongside `type` —
   * including oneOf/anyOf/allOf/not, if/then/else, $ref/$defs/$anchor.
   * Property schemas may carry an `x-mcp-header` annotation to mirror the argument
   * value into an HTTP header on the Streamable HTTP transport.
   * Defaults to JSON Schema 2020-12 when no explicit `$schema` is provided.
   */
  inputSchema: { $schema?: string; type: "object"; [key: string]: unknown };
  /** Structure of CallToolResult.structuredContent. Any valid JSON Schema 2020-12. */
  outputSchema?: { $schema?: string; [key: string]: unknown };
  /** Display name precedence: `title`, `annotations.title`, then `name`. */
  annotations?: ToolAnnotations;
  _meta?: MetaObject;
}

/** NOTE: all properties in ToolAnnotations are **hints**. Clients should never
 *  make tool use decisions based on ToolAnnotations from untrusted servers. */
export interface ToolAnnotations {
  title?: string;
  readOnlyHint?: boolean;    // Default: false
  destructiveHint?: boolean; // Default: true  (meaningful only when readOnlyHint == false)
  idempotentHint?: boolean;  // Default: false (meaningful only when readOnlyHint == false)
  openWorldHint?: boolean;   // Default: true
}

export interface CallToolResult extends Result {
  content: ContentBlock[];
  /** Any JSON value conforming to the tool's outputSchema if one is defined. */
  structuredContent?: unknown;
  /** Tool-originated errors SHOULD be reported here, NOT as a protocol error. */
  isError?: boolean;
}

export interface ElicitRequestFormParams {
  mode?: "form";
  /** The message to present to the user describing what information is requested. */
  message: string;
  /** A restricted subset of JSON Schema. Only top-level properties, no nesting. */
  requestedSchema: {
    $schema?: string;
    type: "object";
    properties: { [key: string]: PrimitiveSchemaDefinition };
    required?: string[];
  };
}

export interface ElicitRequestURLParams {
  mode: "url";
  message: string;
  /** @format uri */
  url: string;
}

export type ElicitRequestParams = ElicitRequestFormParams | ElicitRequestURLParams;

export interface ElicitRequest {
  method: "elicitation/create";
  params: ElicitRequestParams;
}

export type PrimitiveSchemaDefinition =
  StringSchema | NumberSchema | BooleanSchema | EnumSchema;

export interface StringSchema {
  type: "string";
  title?: string;
  description?: string;
  minLength?: number;
  maxLength?: number;
  format?: "email" | "uri" | "date" | "date-time";
  default?: string;
}

export interface ElicitResult {
  /**
   * "accept": User submitted the form/confirmed the action
   * "decline": User explicitly declined the action
   * "cancel": User dismissed without making an explicit choice
   */
  action: "accept" | "decline" | "cancel";
  /** Present only when action is "accept" and mode was "form". */
  content?: { [key: string]: string | number | boolean | string[] };
}

{
  "jsonrpc": "2.0",
  "id": 1,
  "result": {
    "resultType": "input_required",
    "inputRequests": {
      "github_login": {
        "method": "elicitation/create",
        "params": {
          "mode": "form",
          "message": "Please provide your GitHub username",
          "requestedSchema": {
            "type": "object",
            "properties": { "name": { "type": "string" } },
            "required": ["name"]
          }
        }
      }
    },
    "requestState": "AEAD-protected blob"
  }
}

// Client retries the ORIGINAL request with a DIFFERENT JSON-RPC id,
// echoing requestState byte-exact and supplying inputResponses:
// {
//   "github_login": { "action": "accept", "content": { "name": "octocat" } }
// }

{
  "jsonrpc": "2.0",
  "id": 1,
  "error": {
    "code": -32022,
    "message": "Unsupported protocol version",
    "data": {
      "supported": ["2026-07-28", "2025-11-25"],
      "requested": "1900-01-01"
    }
  }
}

