//                    -32020..-32099 reserved for the MCP specification.

export interface DiscoverResult extends CacheableResult {
  /** MCP Protocol Versions this server supports. */
  supportedVersions: string[];
  capabilities: ServerCapabilities;
  /**
   * Natural-language guidance describing the server and its features.
   * Should focus on information that helps the model use the server
   * effectively and should not duplicate tool descriptions.
   */
  instructions?: string;
}

export interface SubscriptionsListenRequestParams extends RequestParams {
  /** The server MUST NOT send notification types the client has not requested. */
  notifications: SubscriptionFilter;
}
export interface SubscriptionsListenRequest extends JSONRPCRequest {
  method: "subscriptions/listen";
  params: SubscriptionsListenRequestParams;
}

